import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
const nativeFs = require('node:fs') as typeof import('node:fs');
import {
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  symlinkSync,
  writeFileSync,
} from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import { brotliDecompressSync } from 'node:zlib';

const backendRoot = path.resolve(__dirname, '..');
const repositoryRoot = path.resolve(backendRoot, '..');
const scannerPath = path.join(backendRoot, 'scripts', 'architecture', 'r12b-planning-public-contracts-scan.cjs');
const runnerPath = path.join(backendRoot, 'scripts', 'architecture', 'r12b-documentation-transition.cjs');
const manifestPath = path.join(backendRoot, 'architecture', 'r12b-planning-public-contracts.json');
const manifestRelative = 'backend/architecture/r12b-planning-public-contracts.json';
const packagePaths = ['backend/package.json', 'admin-web/package.json'];
// Closure. The generated-catalog mirrors reproduce the R12B candidate catalog
// from the R12B-era package commands; after the R12C closure that predecessor
// package is history verified at the recorded lineage commit by
// architecture-governance-portability.test.ts, and the live catalog is
// verified by `node scripts/docs-sync.mjs --check`.
const closure = require(path.join(backendRoot, 'scripts', 'architecture', 'modular-monolith-closure.cjs')).readClosure(repositoryRoot);
const lineageOnly = closure
  ? `R12C is closed (lineage commit ${closure.lineageCommit.slice(0, 12)}): this lineage law is proven at the recorded lineage commit by architecture-governance-portability.test.ts`
  : false;

function r12bEraBackendPackage(): Buffer {
  const successorManifest = path.join(backendRoot, 'architecture', 'r12c-zero-cross-context-dependencies.json');
  if (!existsSync(successorManifest)) return readFileSync(path.join(backendRoot, 'package.json'));
  const r12c = require(path.join(backendRoot, 'scripts', 'architecture', 'r12c-zero-cross-context-dependencies-scan.cjs'));
  const projection = r12c.projectR12cWorkingTreeToPredecessor({
    repositoryRoot,
    manifest: JSON.parse(readFileSync(successorManifest, 'utf8')),
  });
  const bytes = projection.readWorkingFile('backend/package.json');
  assert.equal(Buffer.isBuffer(bytes), true, 'R12C predecessor projection must reconstruct the R12B-era backend/package.json');
  return Buffer.from(bytes);
}
const genesisSha256 = 'e60fbd3d8820a9bfa00199937e0ce44025a32a73f41454786a3d53aef1adf4ad';
const documentPaths = [
  'ARCHITECTURE.md',
  'CHANGELOG.md',
  'docs/project/DECISIONS.md',
  'docs/project/EXECUTION_PLAN.md',
  'docs/project/STATUS.md',
  'docs/README.md',
  'docs/SCRIPTS.md',
];
const portableDocumentAuthorityBrotliBase64 = '';
const genesisLiteral = '{"phase":"R12B","baseCommit":"4d0d3ee91fb32d0432aa3bd69fe018d9a5a323b1","documentationStage":"entry","documents":[{"path":"ARCHITECTURE.md","sha256":"f831577a63cd50537c35b78a160fabfa99317a0e5327a2a5d9035e87892910da"},{"path":"CHANGELOG.md","sha256":"5b86073af49e1f1b05f2d788a376d3d3bc386dfec93b46e7cbfbffac86b3568b"},{"path":"docs/project/DECISIONS.md","sha256":"f2ece280a72c5fad31a626a9c0962ca627c33073cdf7ba93fba4c8deb44a1601"},{"path":"docs/project/EXECUTION_PLAN.md","sha256":"8f46c6ae9112d899a2c9ea97fdc4ca3a36c48ab09c715bc68aff1d570ead72a8"},{"path":"docs/project/STATUS.md","sha256":"0e5740f2c22106235c1618459b60dd2462a5a45a9dfd65c59a7752d91b437831"},{"path":"docs/README.md","sha256":"546dee5d63b03fda63ad9e976af85852c63976e8eb0e48eedf6c460444bcdfb5"},{"path":"docs/SCRIPTS.md","sha256":"975f628fe69bb77cc8237e5929808705a7ad8ee766813b762dd5c6413b34d1d2"}]}';
const sha256 = (value: Buffer | string) => createHash('sha256').update(value).digest('hex');
type DocumentationState = 'entry' | 'candidate-prepared' | 'candidate' | 'activation-prepared' | 'activated';
type PortableStateName = 'entry' | 'candidate' | 'activated';
type PortableSlice = { offset: number; length: number; sha256: string };
type PortablePatch = { path: string; at: number; remove: PortableSlice; insert: PortableSlice; length: number; sha256: string };
const documentationStageContract: Record<DocumentationState, { receipts: number; bytes: PortableStateName }> = {
  entry: { receipts: 0, bytes: 'entry' },
  'candidate-prepared': { receipts: 1, bytes: 'entry' },
  candidate: { receipts: 2, bytes: 'candidate' },
  'activation-prepared': { receipts: 3, bytes: 'candidate' },
  activated: { receipts: 4, bytes: 'activated' },
};
const liveDocumentationState: DocumentationState = 'activated';
const documentationTransitionPairs: ReadonlyArray<readonly [DocumentationState, DocumentationState]> = [
  ['entry', 'candidate-prepared'],
  ['candidate-prepared', 'candidate'],
  ['candidate', 'activation-prepared'],
  ['activation-prepared', 'activated'],
];

const decodePortableDocumentAuthority = () => {
  const packed = brotliDecompressSync(Buffer.from(portableDocumentAuthorityBrotliBase64, 'base64'));
  assert.equal(packed.length > 4, true);
  const metadataLength = packed.readUInt32BE(0);
  const metadata = JSON.parse(packed.subarray(4, 4 + metadataLength).toString('utf8'));
  const payload = packed.subarray(4 + metadataLength);
  assert.equal(metadata.version, 1);
  assert.deepEqual(metadata.paths, documentPaths);
  const readSlice = (record: PortableSlice): Buffer => {
    assert.equal(Number.isSafeInteger(record.offset) && record.offset >= 0, true);
    assert.equal(Number.isSafeInteger(record.length) && record.length >= 0, true);
    assert.equal(record.offset + record.length <= payload.length, true);
    const bytes = Buffer.from(payload.subarray(record.offset, record.offset + record.length));
    assert.equal(bytes.length, record.length);
    assert.equal(Buffer.from(bytes.toString('utf8'), 'utf8').equals(bytes), true);
    assert.equal(sha256(bytes), record.sha256);
    return bytes;
  };
  const entry = new Map<string, Buffer>();
  metadata.entry.forEach((record: PortableSlice & { path: string }, index: number) => {
    assert.equal(record.path, documentPaths[index]);
    entry.set(record.path, readSlice(record));
  });
  const derive = (source: Map<string, Buffer>, patches: PortablePatch[]) => {
    const result = new Map<string, Buffer>();
    patches.forEach((patch, index) => {
      assert.equal(patch.path, documentPaths[index]);
      const from = source.get(patch.path)!;
      const removed = readSlice(patch.remove);
      const inserted = readSlice(patch.insert);
      assert.equal(from.subarray(patch.at, patch.at + removed.length).equals(removed), true);
      const bytes = Buffer.concat([from.subarray(0, patch.at), inserted, from.subarray(patch.at + removed.length)]);
      assert.equal(bytes.length, patch.length);
      assert.equal(Buffer.from(bytes.toString('utf8'), 'utf8').equals(bytes), true);
      assert.equal(sha256(bytes), patch.sha256);
      result.set(patch.path, bytes);
    });
    return result;
  };
  const candidate = derive(entry, metadata.candidate);
  const activated = derive(candidate, metadata.activated);
  return { entry, candidate, activated };
};
const portableDocumentAuthority = decodePortableDocumentAuthority();
const freshPortableDocumentStates = () => Object.fromEntries(
  (['entry', 'candidate', 'activated'] as const).map((state) => [
    state,
    new Map(documentPaths.map((relative) => [relative, Buffer.from(portableDocumentAuthority[state].get(relative)!)])),
  ]),
) as Record<PortableStateName, Map<string, Buffer>>;
const documentRecords = (state: PortableStateName) =>
  documentPaths.map((relative) => ({ path: relative, sha256: sha256(portableDocumentAuthority[state].get(relative)!) }));

const assertPortableAuthorityMatchesManifest = (manifest: any) => {
  const transforms = manifest.inverseTransforms.filter((item: any) => item.kind === 'documentation-transition');
  assert.deepEqual(transforms.map((item: any) => item.path), documentPaths);
  transforms.forEach((item: any, index: number) => {
    assert.equal(item.entrySha256, documentRecords('entry')[index].sha256);
    assert.equal(item.candidateSha256, documentRecords('candidate')[index].sha256);
    assert.equal(item.activatedSha256, documentRecords('activated')[index].sha256);
  });
};

const buildDocumentationManifest = (source: any, state: DocumentationState): any => {
  assertPortableAuthorityMatchesManifest(source);
  const manifest = structuredClone(source);
  manifest.stage = 'strict';
  const documentation = manifest.inverseTransforms.filter((item: any) => item.kind === 'documentation-transition');
  manifest.documentationStage = 'entry';
  manifest.documentationTransitions = [];
  documentation.forEach((item: any, index: number) => {
    item.entrySha256 = documentRecords('entry')[index].sha256;
    item.candidateSha256 = null;
    item.activatedSha256 = null;
  });
  if (state !== 'entry') {
    documentation.forEach((item: any, index: number) => {
      item.candidateSha256 = documentRecords('candidate')[index].sha256;
      item.activatedSha256 = documentRecords('activated')[index].sha256;
    });
    let previousReceiptSha256 = genesisSha256;
    for (let index = 0; index < documentationStageContract[state].receipts; index += 1) {
      const beforeState: PortableStateName = index < 2 ? 'entry' : 'candidate';
      const afterState: PortableStateName = index === 1 ? 'candidate' : index === 3 ? 'activated' : beforeState;
      const unsigned = {
        sequence: index + 1,
        from: documentationTransitionPairs[index][0],
        to: documentationTransitionPairs[index][1],
        previousReceiptSha256,
        beforeDocuments: documentRecords(beforeState),
        afterDocuments: documentRecords(afterState),
        candidateDocuments: documentRecords('candidate'),
        activatedDocuments: documentRecords('activated'),
      };
      const receipt = { ...unsigned, receiptSha256: sha256(JSON.stringify(unsigned)) };
      manifest.documentationTransitions.push(receipt);
      previousReceiptSha256 = receipt.receiptSha256;
    }
  }
  manifest.documentationStage = state;
  return manifest;
};

const assertLiteralDocumentationState = (manifest: any) => {
  const state = manifest.documentationStage as DocumentationState;
  assert.equal(Object.prototype.hasOwnProperty.call(documentationStageContract, state), true);
  assert.equal(manifest.documentationTransitions.length, documentationStageContract[state].receipts);
  let previousReceiptSha256 = genesisSha256;
  manifest.documentationTransitions.forEach((receipt: any, index: number) => {
    assert.equal(receipt.sequence, index + 1);
    assert.equal(receipt.from, documentationTransitionPairs[index][0]);
    assert.equal(receipt.to, documentationTransitionPairs[index][1]);
    assert.equal(receipt.previousReceiptSha256, previousReceiptSha256);
    const beforeState: PortableStateName = index < 2 ? 'entry' : 'candidate';
    const afterState: PortableStateName = index === 1 ? 'candidate' : index === 3 ? 'activated' : beforeState;
    assert.deepEqual(receipt.beforeDocuments, documentRecords(beforeState));
    assert.deepEqual(receipt.afterDocuments, documentRecords(afterState));
    assert.deepEqual(receipt.candidateDocuments, documentRecords('candidate'));
    assert.deepEqual(receipt.activatedDocuments, documentRecords('activated'));
    const { receiptSha256, ...unsigned } = receipt;
    assert.equal(receiptSha256, sha256(JSON.stringify(unsigned)));
    previousReceiptSha256 = receiptSha256;
  });
  if (state === 'entry') {
    for (const item of manifest.inverseTransforms.filter((entry: any) => entry.kind === 'documentation-transition')) {
      assert.equal(item.candidateSha256, null);
      assert.equal(item.activatedSha256, null);
    }
  } else {
    assertPortableAuthorityMatchesManifest(manifest);
  }
};
const loadManifest = () => JSON.parse(readFileSync(manifestPath, 'utf8'));
const scanner = () => require(scannerPath);
const runner = () => require(runnerPath);

const copyFile = (root: string, sourceRoot: string, relative: string) => {
  const target = path.join(root, ...relative.split('/'));
  mkdirSync(path.dirname(target), { recursive: true });
  cpSync(path.join(sourceRoot, ...relative.split('/')), target);
};

const fixture = () => {
  const root = mkdtempSync(path.join(os.tmpdir(), 'aarast-r12b-transition-'));
  const candidateRoot = mkdtempSync(path.join(os.tmpdir(), 'aarast-r12b-candidate-'));
  const activatedRoot = mkdtempSync(path.join(os.tmpdir(), 'aarast-r12b-activated-'));
  const states = freshPortableDocumentStates();
  for (const relative of documentPaths) {
    for (const [preparedRoot, state] of [
      [root, 'entry'],
      [candidateRoot, 'candidate'],
      [activatedRoot, 'activated'],
    ] as const) {
      const target = path.join(preparedRoot, ...relative.split('/'));
      mkdirSync(path.dirname(target), { recursive: true });
      writeFileSync(target, states[state].get(relative)!);
      assert.equal(sha256(readFileSync(target)), documentRecords(state)[documentPaths.indexOf(relative)].sha256);
    }
  }
  const targetManifest = path.join(root, ...manifestRelative.split('/'));
  mkdirSync(path.dirname(targetManifest), { recursive: true });
  const preparedManifest = buildDocumentationManifest(loadManifest(), 'entry');
  preparedManifest.inverseTransforms.forEach((item: any) => {
    if (!['documentation-transition', 'bounded-hunk-replay'].includes(item.kind)) item.intendedFinalSha256 = 'a'.repeat(64);
  });
  const self = preparedManifest.r12bPaths[0];
  self.normalizedSelfSha256 = '0'.repeat(64);
  self.normalizedSelfSha256 = sha256(Buffer.from(`${JSON.stringify(preparedManifest, null, 2)}\n`, 'utf8'));
  writeFileSync(targetManifest, `${JSON.stringify(preparedManifest, null, 2)}\n`);
  assertLiteralDocumentationState(JSON.parse(readFileSync(targetManifest, 'utf8')));
  return { root, candidateRoot, activatedRoot, targetManifest };
};

const manifestSha = (file: string) => sha256(readFileSync(file));
const cleanup = (...roots: string[]) => roots.forEach((root) => rmSync(root, { recursive: true, force: true }));

test('R12B documentation genesis uses the exact canonical UTF-8 preimage', () => {
  assert.equal(sha256(Buffer.from(genesisLiteral, 'utf8')), genesisSha256);
  assert.equal(genesisLiteral.endsWith('\n'), false);
  assert.equal(Buffer.from(genesisLiteral, 'utf8').subarray(0, 3).equals(Buffer.from([0xef, 0xbb, 0xbf])), false);
  const swapped = JSON.parse(genesisLiteral);
  [swapped.documents[0], swapped.documents[1]] = [swapped.documents[1], swapped.documents[0]];
  assert.notEqual(sha256(JSON.stringify(swapped)), genesisSha256);
});

test('R12B live documentation state matches the literal five-stage receipt-prefix contract', () => {
  const api = scanner();
  const manifest = loadManifest();
  assert.equal(api.validateR12bDocumentationTransitions(manifest), manifest.documentationStage);
  assertLiteralDocumentationState(manifest);
  const documentation = manifest.inverseTransforms.filter((item: { kind: string }) => item.kind === 'documentation-transition');
  assert.deepEqual(documentation.map((item: { path: string }) => item.path), documentPaths);
  const liveContract = documentationStageContract[liveDocumentationState];
  assert.equal(manifest.documentationStage, liveDocumentationState);
  assert.equal(manifest.documentationTransitions.length, liveContract.receipts);
  assert.deepEqual(manifest.documentationTransitions, buildDocumentationManifest(manifest, liveDocumentationState).documentationTransitions);
  assert.throws(() => api.validateR12bDocumentationTransitions({ ...manifest, documentationStage: 'entry' }));
  assert.throws(() => api.validateR12bDocumentationTransitions({ ...manifest, documentationTransitions: [{}] }));
});

test('R12B transition runner executes all four receipts with one generated scripts activation no-op', () => {
  assert.equal(existsSync(runnerPath), true, 'R12B transition runner must exist');
  const api = runner();
  assert.deepEqual(Object.keys(api), [
    'planDocumentationTransition',
    'runDocumentationTransition',
    'recoverDocumentationTransition',
    'runCli',
  ]);
  const f = fixture();
  try {
    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(f.targetManifest),
      candidateRoot: f.candidateRoot,
      activatedRoot: f.activatedRoot,
    });
    let manifest = JSON.parse(readFileSync(f.targetManifest, 'utf8'));
    assert.equal(manifest.documentationStage, 'candidate-prepared');
    assert.equal(manifest.documentationTransitions.length, 1);
    assert.equal(manifest.documentationTransitions[0].previousReceiptSha256, genesisSha256);

    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate',
      expectedManifestSha256: manifestSha(f.targetManifest),
      preparedRoot: f.candidateRoot,
    });
    manifest = JSON.parse(readFileSync(f.targetManifest, 'utf8'));
    assert.equal(manifest.documentationStage, 'candidate');
    assert.equal(manifest.documentationTransitions.length, 2);
    for (const relative of documentPaths) {
      assert.deepEqual(readFileSync(path.join(f.root, relative)), readFileSync(path.join(f.candidateRoot, relative)));
    }

    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'activation-prepared',
      expectedManifestSha256: manifestSha(f.targetManifest),
      preparedRoot: f.activatedRoot,
    });
    manifest = JSON.parse(readFileSync(f.targetManifest, 'utf8'));
    assert.equal(manifest.documentationStage, 'activation-prepared');
    assert.equal(manifest.documentationTransitions.length, 3);

    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'activated',
      expectedManifestSha256: manifestSha(f.targetManifest),
      preparedRoot: f.activatedRoot,
    });
    manifest = JSON.parse(readFileSync(f.targetManifest, 'utf8'));
    assert.equal(manifest.documentationStage, 'activated');
    assert.equal(manifest.documentationTransitions.length, 4);
    assert.equal(scanner().validateR12bDocumentationTransitions(manifest), 'activated');
    for (const relative of documentPaths) {
      assert.deepEqual(readFileSync(path.join(f.root, relative)), readFileSync(path.join(f.activatedRoot, relative)));
    }
  } finally {
    cleanup(f.root, f.candidateRoot, f.activatedRoot);
  }
});

test('R12B candidate preparation enforces generated scripts and narrative hash relationships by exact path', () => {
  const api = runner();

  const entryEquality = fixture();
  try {
    const entryScripts = path.join(entryEquality.root, 'docs', 'SCRIPTS.md');
    writeFileSync(path.join(entryEquality.candidateRoot, 'docs', 'SCRIPTS.md'), readFileSync(entryScripts));
    writeFileSync(path.join(entryEquality.activatedRoot, 'docs', 'SCRIPTS.md'), readFileSync(entryScripts));
    assert.throws(() => api.runDocumentationTransition({
      repositoryRoot: entryEquality.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(entryEquality.targetManifest),
      candidateRoot: entryEquality.candidateRoot,
      activatedRoot: entryEquality.activatedRoot,
    }), /candidate documentation must differ from entry/u);
  } finally {
    cleanup(entryEquality.root, entryEquality.candidateRoot, entryEquality.activatedRoot);
  }

  for (const relative of documentPaths.slice(0, -1)) {
    const narrativeEquality = fixture();
    try {
      writeFileSync(
        path.join(narrativeEquality.activatedRoot, ...relative.split('/')),
        readFileSync(path.join(narrativeEquality.candidateRoot, ...relative.split('/'))),
      );
      assert.throws(() => api.runDocumentationTransition({
        repositoryRoot: narrativeEquality.root,
        to: 'candidate-prepared',
        expectedManifestSha256: manifestSha(narrativeEquality.targetManifest),
        candidateRoot: narrativeEquality.candidateRoot,
        activatedRoot: narrativeEquality.activatedRoot,
      }), /narrative candidate and activated states must be distinct/u, relative);
    } finally {
      cleanup(narrativeEquality.root, narrativeEquality.candidateRoot, narrativeEquality.activatedRoot);
    }
  }

  const generatedInequality = fixture();
  try {
    const activatedScripts = path.join(generatedInequality.activatedRoot, 'docs', 'SCRIPTS.md');
    writeFileSync(activatedScripts, Buffer.concat([
      readFileSync(activatedScripts),
      Buffer.from('non-canonical generated activation\n', 'utf8'),
    ]));
    assert.throws(() => api.runDocumentationTransition({
      repositoryRoot: generatedInequality.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(generatedInequality.targetManifest),
      candidateRoot: generatedInequality.candidateRoot,
      activatedRoot: generatedInequality.activatedRoot,
    }), /generated scripts candidate and activated bytes must match/u);
  } finally {
    cleanup(generatedInequality.root, generatedInequality.candidateRoot, generatedInequality.activatedRoot);
  }
});

test('R12B generated scripts are canonical and byte-identical in both outside-repository mirrors', { skip: lineageOnly }, () => {
  const candidateRoot = mkdtempSync(path.join(os.tmpdir(), 'aarast-r12b-docs-sync-candidate-'));
  const activatedRoot = mkdtempSync(path.join(os.tmpdir(), 'aarast-r12b-docs-sync-activated-'));
  try {
    const inventory = execFileSync('git', ['ls-files', '-co', '--exclude-standard', '-z'], {
      cwd: repositoryRoot,
      encoding: 'utf8',
    }).split('\0').filter(Boolean);
    for (const relative of inventory) {
      if (!existsSync(path.join(repositoryRoot, ...relative.split('/')))) continue;
      copyFile(candidateRoot, repositoryRoot, relative);
      copyFile(activatedRoot, repositoryRoot, relative);
    }
    // R12B's generated catalog was produced from the R12B-era package
    // commands. With the R12C successor present, the mirrors take that exact
    // predecessor package.json from the successor projection; without it the
    // live file is already the R12B-era file.
    for (const root of [candidateRoot, activatedRoot]) {
      writeFileSync(path.join(root, 'backend', 'package.json'), r12bEraBackendPackage());
    }
    for (const root of [candidateRoot, activatedRoot]) {
      writeFileSync(path.join(root, 'docs', 'SCRIPTS.md'), portableDocumentAuthority.entry.get('docs/SCRIPTS.md')!);
      assert.equal(sha256(readFileSync(path.join(root, 'docs', 'SCRIPTS.md'))), documentRecords('entry').find((item) => item.path === 'docs/SCRIPTS.md')!.sha256);
      execFileSync(process.execPath, [path.join(root, 'scripts', 'docs-sync.mjs')], {
        cwd: root,
        encoding: 'utf8',
        stdio: 'pipe',
      });
      execFileSync(process.execPath, [path.join(root, 'scripts', 'docs-sync.mjs'), '--check'], {
        cwd: root,
        encoding: 'utf8',
        stdio: 'pipe',
      });
    }
    // docs-sync must never rewrite the package files it reads.
    for (const relative of packagePaths) {
      const expected = relative === 'backend/package.json'
        ? r12bEraBackendPackage()
        : readFileSync(path.join(repositoryRoot, ...relative.split('/')));
      assert.deepEqual(readFileSync(path.join(candidateRoot, ...relative.split('/'))), expected, `${relative} candidate`);
      assert.deepEqual(readFileSync(path.join(activatedRoot, ...relative.split('/'))), expected, `${relative} activated`);
    }
    const entryScripts = portableDocumentAuthority.entry.get('docs/SCRIPTS.md')!;
    const candidateScripts = readFileSync(path.join(candidateRoot, 'docs', 'SCRIPTS.md'));
    const activatedScripts = readFileSync(path.join(activatedRoot, 'docs', 'SCRIPTS.md'));
    assert.notEqual(sha256(candidateScripts), sha256(entryScripts));
    assert.deepEqual(candidateScripts, activatedScripts);
    assert.equal(sha256(candidateScripts), sha256(activatedScripts));
    assert.equal(sha256(candidateScripts), documentRecords('candidate').find((item) => item.path === 'docs/SCRIPTS.md')!.sha256);
  } finally {
    cleanup(candidateRoot, activatedRoot);
  }
});

test('R12B transition validation rejects jumps, stale manifests, reordered documents, and unsafe roots', () => {
  const api = runner();
  const f = fixture();
  try {
    assert.throws(() => api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate',
      expectedManifestSha256: manifestSha(f.targetManifest),
      preparedRoot: f.candidateRoot,
    }), /transition|next|state/u);
    assert.throws(() => api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate-prepared',
      expectedManifestSha256: '0'.repeat(64),
      candidateRoot: f.candidateRoot,
      activatedRoot: f.activatedRoot,
    }), /manifest|hash/u);
    const outside = mkdtempSync(path.join(os.tmpdir(), 'aarast-r12b-outside-'));
    try {
      assert.throws(() => api.runDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate-prepared',
        expectedManifestSha256: manifestSha(f.targetManifest),
        candidateRoot: outside,
        activatedRoot: f.activatedRoot,
      }), /document|missing|prepared/u);
    } finally {
      cleanup(outside);
    }
    // The symlink target is a fixture-local copy: a probe must never give the
    // code under test a write path into the real repository.
    const link = path.join(f.candidateRoot, 'ARCHITECTURE.md');
    const linkTarget = path.join(f.root, 'symlink-target-ARCHITECTURE.md');
    writeFileSync(linkTarget, readFileSync(link));
    rmSync(link);
    symlinkSync(linkTarget, link);
    assert.throws(() => api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(f.targetManifest),
      candidateRoot: f.candidateRoot,
      activatedRoot: f.activatedRoot,
    }), /symlink|reparse|plain file/u);
  } finally {
    cleanup(f.root, f.candidateRoot, f.activatedRoot);
  }
});

test('R12B publication rolls back every completed file boundary and recovery removes transaction artifacts', () => {
  const api = runner();
  for (let boundary = 1; boundary <= documentPaths.length; boundary += 1) {
    const f = fixture();
    try {
      api.runDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate-prepared',
        expectedManifestSha256: manifestSha(f.targetManifest),
        candidateRoot: f.candidateRoot,
        activatedRoot: f.activatedRoot,
      });
      const beforeManifest = readFileSync(f.targetManifest);
      const before = new Map(documentPaths.map((relative) => [relative, readFileSync(path.join(f.root, relative))]));
      let replacements = 0;
      assert.throws(() => api.runDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate',
        expectedManifestSha256: manifestSha(f.targetManifest),
        preparedRoot: f.candidateRoot,
        replaceFile: (operation: () => void) => {
          operation();
          replacements += 1;
          if (replacements === boundary) throw new Error(`injected-boundary-${boundary}`);
        },
      }), new RegExp(`injected-boundary-${boundary}`, 'u'));
      assert.deepEqual(readFileSync(f.targetManifest), beforeManifest);
      for (const relative of documentPaths) assert.deepEqual(readFileSync(path.join(f.root, relative)), before.get(relative));
      api.recoverDocumentationTransition({ repositoryRoot: f.root });
      assert.equal(existsSync(path.join(f.root, 'backend', 'architecture', '.r12b-documentation-transition.json')), false);
    } finally {
      cleanup(f.root, f.candidateRoot, f.activatedRoot);
    }
  }
});

test('R12B receipt validation rejects forged prefixes and document order drift', () => {
  const api = runner();
  const validation = scanner();
  const f = fixture();
  try {
    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(f.targetManifest),
      candidateRoot: f.candidateRoot,
      activatedRoot: f.activatedRoot,
    });
    const manifest = JSON.parse(readFileSync(f.targetManifest, 'utf8'));
    const mutations = [
      (value: any) => { value.documentationTransitions[0].previousReceiptSha256 = '0'.repeat(64); },
      (value: any) => { value.documentationTransitions[0].sequence = 2; },
      (value: any) => { value.documentationTransitions[0].receiptSha256 = 'f'.repeat(64); },
      (value: any) => { [value.documentationTransitions[0].beforeDocuments[0], value.documentationTransitions[0].beforeDocuments[1]] = [value.documentationTransitions[0].beforeDocuments[1], value.documentationTransitions[0].beforeDocuments[0]]; },
      (value: any) => { value.documentationTransitions.push(structuredClone(value.documentationTransitions[0])); },
      (value: any) => { value.documentationStage = 'activated'; },
    ];
    for (const change of mutations) {
      const forged = structuredClone(manifest);
      change(forged);
      assert.throws(() => validation.validateR12bDocumentationTransitions(forged));
    }
  } finally {
    cleanup(f.root, f.candidateRoot, f.activatedRoot);
  }
});

test('R12B publication never removes or moves away a live target during replacement', () => {
  const api = runner();
  const f = fixture();
  const targetPaths = new Set([f.targetManifest, ...documentPaths.map((relative) => path.join(f.root, ...relative.split('/')))]);
  const removed: string[] = [];
  const movedAway: string[] = [];
  const originalRm = nativeFs.rmSync;
  const originalRename = nativeFs.renameSync;
  (nativeFs as any).rmSync = (file: string, ...args: any[]) => {
    if (targetPaths.has(path.resolve(file))) removed.push(path.resolve(file));
    return originalRm(file, ...args);
  };
  (nativeFs as any).renameSync = (source: string, destination: string) => {
    if (targetPaths.has(path.resolve(source))) movedAway.push(path.resolve(source));
    return originalRename(source, destination);
  };
  try {
    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(f.targetManifest),
      candidateRoot: f.candidateRoot,
      activatedRoot: f.activatedRoot,
    });
    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate',
      expectedManifestSha256: manifestSha(f.targetManifest),
      preparedRoot: f.candidateRoot,
    });
    assert.deepEqual(removed, []);
    assert.deepEqual(movedAway, []);
  } finally {
    (nativeFs as any).rmSync = originalRm;
    (nativeFs as any).renameSync = originalRename;
    cleanup(f.root, f.candidateRoot, f.activatedRoot);
  }
});

test('R12B child interruption leaves a recoverable journal at every document boundary', () => {
  const childCode = [
    "const runner = require(process.argv[1]);",
    'const options = JSON.parse(process.argv[2]);',
    'let boundary = 0; const interruptAt = Number(process.argv[3]);',
    'options.replaceFile = (operation) => { operation(); boundary += 1; if (boundary === interruptAt) process.exit(86); };',
    'try { runner.runDocumentationTransition(options); } catch (error) { process.exitCode = 2; }',
  ].join('\n');
  for (let boundary = 1; boundary <= documentPaths.length; boundary += 1) {
    const f = fixture();
    try {
      const first = runner();
      first.runDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate-prepared',
        expectedManifestSha256: manifestSha(f.targetManifest),
        candidateRoot: f.candidateRoot,
        activatedRoot: f.activatedRoot,
      });
      const beforeManifest = readFileSync(f.targetManifest);
      const before = new Map(documentPaths.map((relative) => [relative, readFileSync(path.join(f.root, relative))]));
      const options = {
        repositoryRoot: f.root,
        to: 'candidate',
        expectedManifestSha256: manifestSha(f.targetManifest),
        preparedRoot: f.candidateRoot,
      };
      const child = spawnSync(process.execPath, ['-e', childCode, runnerPath, JSON.stringify(options), String(boundary)], { encoding: 'utf8', windowsHide: true });
      assert.equal(child.status, 86, `child interruption boundary ${boundary}`);
      const journal = path.join(f.root, ...'backend/architecture/.r12b-documentation-transition.json'.split('/'));
      assert.equal(existsSync(journal), true, `journal boundary ${boundary}`);
      assert.throws(() => first.planDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate',
        expectedManifestSha256: manifestSha(f.targetManifest),
        preparedRoot: f.candidateRoot,
      }), /recovery|required|journal/u);
      first.recoverDocumentationTransition({ repositoryRoot: f.root });
      assert.deepEqual(readFileSync(f.targetManifest), beforeManifest);
      for (const relative of documentPaths) assert.deepEqual(readFileSync(path.join(f.root, relative)), before.get(relative));
      assert.equal(existsSync(journal), false);
    } finally {
      cleanup(f.root, f.candidateRoot, f.activatedRoot);
    }
  }
});

test('R12B transition CLI rejects missing, duplicate, extra, and irrelevant options', () => {
  const invalid = [
    [],
    ['--to', 'candidate-prepared'],
    ['--expected-manifest-sha256', '0'.repeat(64), '--to', 'candidate-prepared'],
    ['--to', 'candidate-prepared', '--expected-manifest-sha256', '0'.repeat(64), '--to', 'candidate-prepared'],
    ['--to', 'candidate-prepared', '--expected-manifest-sha256', '0'.repeat(64), '--force', 'yes'],
    ['--recover', '--to', 'candidate-prepared'],
    ['--to', 'candidate-prepared', '--expected-manifest-sha256', '0'.repeat(64), '--candidate-root'],
  ];
  for (const args of invalid) {
    assert.throws(() => execFileSync(process.execPath, [runnerPath, ...args], { cwd: backendRoot, encoding: 'utf8', stdio: 'pipe' }), (error: any) => error.status === 2);
  }
});

test('R12B transitions fail closed on stale journal, backup, and temporary artifacts without deleting them', () => {
  const api = runner();
  const f = fixture();
  const stalePaths = [
    path.join(f.root, ...'backend/architecture/.r12b-documentation-transition.json'.split('/')),
    `${path.join(f.root, 'ARCHITECTURE.md')}.r12b-documentation.bak`,
    `${path.join(f.root, 'ARCHITECTURE.md')}.r12b-documentation.tmp`,
  ];
  try {
    for (const stale of stalePaths) {
      mkdirSync(path.dirname(stale), { recursive: true });
      writeFileSync(stale, 'stale');
      assert.throws(() => api.planDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate-prepared',
        expectedManifestSha256: manifestSha(f.targetManifest),
        candidateRoot: f.candidateRoot,
        activatedRoot: f.activatedRoot,
      }), /stale|recovery|artifact/u);
      assert.equal(existsSync(stale), true);
      nativeFs.rmSync(stale, { force: true });
    }
  } finally {
    cleanup(f.root, f.candidateRoot, f.activatedRoot);
  }
});

test('R12B atomic replacement fails closed on Windows rename errors without copying or writing the live target', () => {
  const api = runner();
  const f = fixture();
  try {
    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(f.targetManifest),
      candidateRoot: f.candidateRoot,
      activatedRoot: f.activatedRoot,
    });
    const target = path.join(f.root, 'ARCHITECTURE.md');
    const before = readFileSync(target);
    const originalRename = nativeFs.renameSync;
    const originalCopy = nativeFs.copyFileSync;
    const originalWrite = nativeFs.writeFileSync;
    let copyCalls = 0;
    let liveWrites = 0;
    (nativeFs as any).renameSync = (source: string, destination: string) => {
      if (path.resolve(destination) === path.resolve(target) && source.endsWith('.r12b-documentation.tmp')) {
        const error: any = new Error('injected EEXIST');
        error.code = 'EEXIST';
        throw error;
      }
      return originalRename(source, destination);
    };
    (nativeFs as any).copyFileSync = (...args: any[]) => { copyCalls += 1; return Reflect.apply(originalCopy as any, nativeFs, args); };
    (nativeFs as any).writeFileSync = (file: string, ...args: any[]) => {
      if (path.resolve(file) === path.resolve(target)) liveWrites += 1;
      return Reflect.apply(originalWrite as any, nativeFs, [file, ...args]);
    };
    try {
      assert.throws(() => api.runDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate',
        expectedManifestSha256: manifestSha(f.targetManifest),
        preparedRoot: f.candidateRoot,
      }), /EEXIST|atomic|replacement/u);
      assert.deepEqual(readFileSync(target), before);
      assert.equal(copyCalls, 0);
      assert.equal(liveWrites, 0);
    } finally {
      (nativeFs as any).renameSync = originalRename;
      (nativeFs as any).copyFileSync = originalCopy;
      (nativeFs as any).writeFileSync = originalWrite;
    }
  } finally {
    cleanup(f.root, f.candidateRoot, f.activatedRoot);
  }
});

test('R12B rollback and recovery retain the journal when atomic restoration rename fails, then recover exactly', () => {
  const api = runner();
  const f = fixture();
  const journal = path.join(f.root, ...'backend/architecture/.r12b-documentation-transition.json'.split('/'));
  try {
    api.runDocumentationTransition({
      repositoryRoot: f.root,
      to: 'candidate-prepared',
      expectedManifestSha256: manifestSha(f.targetManifest),
      candidateRoot: f.candidateRoot,
      activatedRoot: f.activatedRoot,
    });
    const beforeManifest = readFileSync(f.targetManifest);
    const before = new Map(documentPaths.map((relative) => [relative, readFileSync(path.join(f.root, relative))]));
    const originalRename = nativeFs.renameSync;
    let failRestoreRename = true;
    (nativeFs as any).renameSync = (source: string, destination: string) => {
      if (failRestoreRename && source.endsWith('.r12b-documentation.restore.tmp')) {
        const error: any = new Error('injected restore EBUSY');
        error.code = 'EBUSY';
        throw error;
      }
      return originalRename(source, destination);
    };
    try {
      assert.throws(() => api.runDocumentationTransition({
        repositoryRoot: f.root,
        to: 'candidate',
        expectedManifestSha256: manifestSha(f.targetManifest),
        preparedRoot: f.candidateRoot,
        replaceFile: (operation: () => void) => { operation(); throw new Error('injected publication failure'); },
      }), /restore|publication|EBUSY/u);
      assert.equal(existsSync(journal), true);
      assert.equal(existsSync(`${path.join(f.root, 'ARCHITECTURE.md')}.r12b-documentation.bak`), true);
      failRestoreRename = false;
      api.recoverDocumentationTransition({ repositoryRoot: f.root });
    } finally {
      (nativeFs as any).renameSync = originalRename;
    }
    assert.deepEqual(readFileSync(f.targetManifest), beforeManifest);
    for (const relative of documentPaths) assert.deepEqual(readFileSync(path.join(f.root, relative)), before.get(relative));
    assert.equal(existsSync(journal), false);
  } finally {
    cleanup(f.root, f.candidateRoot, f.activatedRoot);
  }
});
